begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_function('public','decide_flight_request',array['uuid','uuid','text'],'Owner decision RPC exists');
-- Everything below is owned fictional data and rolls back with this test.
insert into auth.users(id,email) select ('19300000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'decision-'||n||'@example.invalid' from generate_series(1,6) n;
insert into public.memberships(user_id,role) select ('19300000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=4 then 'admin' else 'member' end::public.member_role from generate_series(1,5) n;
insert into public.profiles(user_id,display_name,home_airport,pilot_designation) select ('19300000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Decision requester','KPAO','licensed' from generate_series(2,3) n;
insert into public.flights(id,owner_id,departure_airport,destination_airport,departure_at,departure_timezone,aircraft_description,pilot_places,visibility)
select ('19310000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=12 then '19300000-0000-4000-8000-000000000005'::uuid else '19300000-0000-4000-8000-000000000001'::uuid end,'KPAO','KSQL',now()+interval '2 days','UTC','C172',1,case when n=9 then 'PRIVATE' else 'NETWORK' end::public.flight_visibility from generate_series(1,12) n;
insert into public.flight_recipients(flight_id,user_id) values('19310000-0000-4000-8000-000000000009','19300000-0000-4000-8000-000000000002');
insert into public.flight_requests(id,flight_id,requester_id,introductory_note)
select ('19320000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('19310000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'19300000-0000-4000-8000-000000000002','Original introduction' from generate_series(1,12) n;
insert into public.flight_requests(id,flight_id,requester_id) values('19320000-0000-4000-8000-000000000099','19310000-0000-4000-8000-000000000001','19300000-0000-4000-8000-000000000003');
create temporary table original_request as select id,flight_id,requester_id,created_at,introductory_note from public.flight_requests where id='19320000-0000-4000-8000-000000000001';
create function pg_temp.decide(f integer default 1,r integer default 1,d text default 'accepted') returns jsonb language sql as $$
 select public.decide_flight_request(('19310000-0000-4000-8000-'||lpad(f::text,12,'0'))::uuid,('19320000-0000-4000-8000-'||lpad(r::text,12,'0'))::uuid,d);
$$;
create function pg_temp.actor(n integer) returns text language sql as $$ select set_config('request.jwt.claims',json_build_object('sub',('19300000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'role','authenticated','user_metadata',json_build_object('role','admin'))::text,true); $$;
select ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='public.decide_flight_request(uuid,uuid,text)'::regprocedure),'Definer RPC has fixed empty search path');
select ok(has_function_privilege('authenticated','public.decide_flight_request(uuid,uuid,text)','EXECUTE'),'Authenticated execute granted');
select ok(not has_function_privilege('anon','public.decide_flight_request(uuid,uuid,text)','EXECUTE'),'Anonymous execute revoked');
select ok(not has_function_privilege('service_role','public.decide_flight_request(uuid,uuid,text)','EXECUTE'),'Service-role execute revoked');
set local role anon;
select throws_ok($$select pg_temp.decide()$$,'42501',null,'Anonymous cannot decide');
reset role;
set local role service_role;
select throws_ok($$select pg_temp.decide()$$,'42501',null,'Service role cannot execute decision RPC');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{}',true);
select throws_ok($$select pg_temp.decide()$$,'42501',null,'Missing identity denied');
select pg_temp.actor(6);
select throws_ok($$select pg_temp.decide()$$,'42501',null,'Missing membership cannot use spoofed admin claim');
select pg_temp.actor(4);
select throws_ok($$select pg_temp.decide()$$,'42501',null,'Unrelated admin denied');
select pg_temp.actor(2);
select throws_ok($$select pg_temp.decide()$$,'42501',null,'Requester cannot decide own request');
select pg_temp.actor(1);
select throws_ok($$select pg_temp.decide(99)$$,'42501',null,'Missing flight shares owner denial');
select throws_ok($$select pg_temp.decide(12,12)$$,'42501',null,'Other owner flight shares owner denial');
select throws_ok($$select public.decide_flight_request(null,'19320000-0000-4000-8000-000000000001','accepted')$$,'22023',null,'Null flight rejected');
select throws_ok($$select public.decide_flight_request('19310000-0000-4000-8000-000000000001',null,'accepted')$$,'22023',null,'Null request rejected');
select throws_ok($$select pg_temp.decide(1,1,null)$$,'22023',null,'Null decision rejected');
select throws_ok($$select pg_temp.decide(1,1,'cancelled')$$,'22023',null,'Unsupported transition rejected');
select is(pg_temp.decide(1,2),'{"code":"request_unavailable"}'::jsonb,'Request from another owned flight cannot be rebound');
select is(pg_temp.decide(1,98),'{"code":"request_unavailable"}'::jsonb,'Unknown request shares unavailable outcome');
select throws_ok($$update public.flight_requests set status='accepted'$$,'42501',null,'Direct acceptance stays closed');
select is(pg_temp.decide(),'{"code":"decided","requestId":"19320000-0000-4000-8000-000000000001","status":"accepted"}'::jsonb,'Owner accepts pending request with minimal confirmation');
select is(pg_temp.decide(1,99),'{"code":"capacity_full"}'::jsonb,'Full capacity is a distinct bounded result');
select is((select status::text from public.flight_requests where id='19320000-0000-4000-8000-000000000099'),'pending','Capacity loser stays pending');
reset role;
create temporary table accepted_snapshot as select to_jsonb(r) as row from public.flight_requests r where id='19320000-0000-4000-8000-000000000001';
update public.flights set departure_at=now()-interval '1 day' where id='19310000-0000-4000-8000-000000000001';
set local role authenticated;
select is(pg_temp.decide()->>'code','already_decided','Matching acceptance retry confirms retained history after departure');
select is(pg_temp.decide(1,1,'declined'),'{"code":"request_conflict"}'::jsonb,'Decline cannot undo acceptance');
reset role;
select is((select to_jsonb(r) from public.flight_requests r where id='19320000-0000-4000-8000-000000000001'),(select row from accepted_snapshot),'Acceptance retry and conflict preserve entire record');
select is((select introductory_note from public.flight_requests where id='19320000-0000-4000-8000-000000000001'),'Original introduction','Decision preserves introduction');
select results_eq($$select id,flight_id,requester_id,created_at,introductory_note from public.flight_requests where id='19320000-0000-4000-8000-000000000001'$$,$$select * from original_request$$,'Decision preserves original identity, creation time and note');
update public.flight_requests set status='withdrawn' where id='19320000-0000-4000-8000-000000000004';
update public.flight_requests set status='cancelled' where id='19320000-0000-4000-8000-000000000005';
update public.flights set departure_at=now()-interval '1 day' where id='19310000-0000-4000-8000-000000000007';
update public.flights set status='cancelled' where id='19310000-0000-4000-8000-000000000008';
delete from public.flight_recipients where flight_id='19310000-0000-4000-8000-000000000009';
set local role authenticated;
select is(pg_temp.decide(4,4)->>'code','request_conflict','Withdrawn request cannot be accepted');
select is(pg_temp.decide(5,5,'declined')->>'code','request_conflict','Cancelled request cannot be declined');
select is(pg_temp.decide(7,7)->>'code','request_ineligible','Past departure blocks new acceptance');
select is(pg_temp.decide(8,8)->>'code','request_ineligible','Closed flight blocks acceptance');
select is(pg_temp.decide(9,9)->>'code','request_ineligible','Missing PRIVATE selection blocks acceptance');
select is(pg_temp.decide(6,6,'declined')->>'code','decided','Owner declines pending request');
select is(pg_temp.decide(6,6,'accepted')->>'code','request_conflict','Declined request cannot revive');
reset role;
create temporary table declined_snapshot as select to_jsonb(r) as row from public.flight_requests r where id='19320000-0000-4000-8000-000000000006';
set local role authenticated;
select is(pg_temp.decide(6,6,'declined')->>'code','already_decided','Decline retry confirms history');
reset role;
select is((select to_jsonb(r) from public.flight_requests r where id='19320000-0000-4000-8000-000000000006'),(select row from declined_snapshot),'Decline retry leaves entire record unchanged');
delete from public.profiles where user_id='19300000-0000-4000-8000-000000000002';
set local role authenticated;
select is(pg_temp.decide(10,10)->>'code','request_ineligible','Missing licensed profile blocks acceptance');
reset role;
insert into public.profiles(user_id,display_name,home_airport,pilot_designation) values('19300000-0000-4000-8000-000000000002','Restored requester','KPAO','licensed');
update public.memberships set status='disabled',disabled_at=now(),disabled_reason='Owned decision test' where user_id='19300000-0000-4000-8000-000000000002';
set local role authenticated;
select is(pg_temp.decide(11,11)->>'code','request_ineligible','Disabled requester blocks acceptance');
select is(pg_temp.decide(11,11,'declined')->>'code','decided','Disabled requester does not prevent terminal decline');
select is(pg_temp.decide(7,7,'declined')->>'code','decided','Past departure does not prevent terminal decline');
select is(pg_temp.decide(8,8,'declined')->>'code','decided','Closed flight does not prevent terminal decline');
select is(pg_temp.decide(9,9,'declined')->>'code','decided','Lost PRIVATE selection does not prevent terminal decline');
reset role;
update public.memberships set status='disabled',disabled_at=now(),disabled_reason='Owned owner test' where user_id='19300000-0000-4000-8000-000000000005';
set local role authenticated;
select pg_temp.actor(5);
select throws_ok($$select pg_temp.decide(12,12)$$,'42501',null,'Disabled actual owner cannot accept');
select throws_ok($$select pg_temp.decide(12,12,'declined')$$,'42501',null,'Disabled actual owner cannot decline');
reset role;
select * from finish();
rollback;
